// PICKING_ASYNC_SUBMIT - Guard: the inputs, the request's shape (at most 2,000 lines), the session tenant. FORCE_COMPLETE
// (Picking 1d) carries no lines: PREPARE plans it from the database
const MAX_LINES = 2000;
const submitGuard = function submitGuard(input) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
  const inp = input || {};
  const tenantId = s(inp.systemTenantId);
  const pickingId = s(inp.pickingId);
  const org = s(inp.organizationId);
  const op = s(inp.operation).toUpperCase() || "CONFIRM";
  const key = s(inp.idempotencyKey);
  const bad = (why) => ({ route: "REJECT", tenantId: "0", pickingId: "0", organizationId: "0", operation: op, idempotencyKey: "", request: "", lineCount: 0, moveRowsJson: "[]", result_code: "400", result_message: why });
  if (!/^[0-9]{1,20}$/.test(tenantId)) return bad("no session tenant");
  if (!/^[0-9]{1,20}$/.test(pickingId)) return bad("picking_id: digits only");
  if (!/^[0-9]{1,20}$/.test(org)) return bad("organization_id: digits only");
  // STATUS: read-only, the Picking's latest job for the form (the browser cannot read gd_async_job itself)
  if (op === "STATUS") return { route: "STATUS", tenantId: tenantId, pickingId: pickingId, organizationId: org, operation: op, idempotencyKey: "", request: "", lineCount: 0, moveRowsJson: "[]", result_code: "", result_message: "" };
  if (!/^[A-Za-z0-9:_|-]{16,128}$/.test(key)) return bad("idempotency_key: 16-128 of A-Z a-z 0-9 : _ | -");
  if (op !== "CONFIRM" && op !== "PICK_ALL_REMAINING" && op !== "FORCE_COMPLETE") return bad("operation must be CONFIRM, PICK_ALL_REMAINING or FORCE_COMPLETE");
  let payload = inp.payload;
  if (typeof payload === "string") {
    try {
      payload = payload ? JSON.parse(payload) : {};
    } catch (e) {
      return bad("payload is not valid JSON");
    }
  }
  payload = payload && typeof payload === "object" ? payload : {};
  const id = (v) => (/^[0-9]{1,20}$/.test(s(v)) ? s(v) : "");
  const lines = [];
  for (const ln of op !== "FORCE_COMPLETE" && Array.isArray(payload.lines) ? payload.lines : []) {
    const rowId = id(ln && ln.row_id);
    const qty = Number(ln && ln.qty);
    if (!rowId) return bad("a line has no row_id");
    if (!isFinite(qty) || qty < 0) return bad("line " + rowId + ": the picked quantity is not a number");
    if (qty === 0) continue;
    // a unit / bin / batch that is not an id would silently pick in the order unit or from the wrong place: refuse it
    for (const k of ["pick_uom", "target_location_id", "target_batch_id"]) if (s(ln[k]) && !id(ln[k])) return bad("line " + rowId + ": " + k + " is not an id");
    const out = { row_id: rowId, qty: qty, pick_uom: id(ln.pick_uom) };
    // sent = the form's value ("" = no move); not sent = PREPARE reads the stored line
    for (const k of ["target_location_id", "target_batch_id"]) if (Object.prototype.hasOwnProperty.call(ln, k)) out[k] = id(ln[k]);
    for (const k of ["remark", "remark_2", "remark_3"]) if (ln[k] !== undefined && ln[k] !== null) out[k] = String(ln[k]);
    if (Array.isArray(ln.attachment)) out.attachment = ln.attachment;
    lines.push(out);
  }
  if (op === "CONFIRM" && !lines.length) return bad("Cannot complete picking. At least one item must have picked quantity greater than 0.");
  if (lines.length > MAX_LINES) return bad("this confirmation has " + lines.length + " picked lines; the maximum is " + MAX_LINES);
  const headerPatch = op !== "FORCE_COMPLETE" && payload.header_patch && typeof payload.header_patch === "object" && !Array.isArray(payload.header_patch) ? payload.header_patch : {};
  const request = { v: 1, operation: op, picking_id: pickingId, confirmed_by: s(inp.confirmedBy).slice(0, 100), lines: op === "CONFIRM" ? lines : [], header_patch: headerPatch };
  // sql_node_PSmove's input, digits only: a sent target ("0" = sent empty, no move) or null (not sent: the stored line's)
  const sent = (o, k) => (Object.prototype.hasOwnProperty.call(o, k) ? o[k] || "0" : null);
  const moveRows = request.lines.map((l) => ({ r: l.row_id, l: sent(l, "target_location_id"), b: sent(l, "target_batch_id") }));
  return { route: "CONTINUE", tenantId: tenantId, pickingId: pickingId, organizationId: org, operation: op, idempotencyKey: key, request: JSON.stringify(request), lineCount: request.lines.length, moveRowsJson: JSON.stringify(moveRows), result_code: "", result_message: "" };
};
const res = submitGuard({ pickingId: [{{workflowparams:picking_id}}][0], organizationId: [{{workflowparams:organization_id}}][0], operation: [{{workflowparams:operation}}][0], idempotencyKey: [{{workflowparams:idempotency_key}}][0], payload: [{{workflowparams:payload}}][0], confirmedBy: [{{workflowparams:confirmed_by}}][0], systemTenantId: [{{system:tenantId}}][0] });
console.log("submit guard", JSON.stringify({ route: res.route, picking: res.pickingId, op: res.operation, lines: res.lineCount, message: res.result_message }));
return res;

// PICKING_ASYNC_SUBMIT - Status: the Picking's latest CONFIRM_PICKING job (open -> the form shows "being saved"; FAILED /
// REQUIRES_REVIEW / a reduced line -> the form reports it once). A force complete (Picking 1d) also names its operation, its
// progress and the delivery edits the screen must run (kick: GD_EDIT_WORKER, one call per id)
const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const rows = [{{node:sql_node_PSstatus.data}}][0];
const job = (Array.isArray(rows) ? rows : rows ? [rows] : []).filter((r) => r && s(r.id))[0] || null;
return job
  ? { route: "STATUS", result_code: s(job.error_code), result_message: s(job.error_message) || s(job.progress_message), job_id: s(job.id), job_status: s(job.job_status),
      operation: s(job.operation) || "CONFIRM", progress_percent: Number(job.progress_percent) || 0, kick: s(job.kick) ? s(job.kick).split(",") : [] }
  : { route: "STATUS", result_code: "", result_message: "", job_id: "", job_status: "", operation: "", progress_percent: 0, kick: [] };

// PICKING_ASYNC_SUBMIT - Decide: the Picking, its setup and its jobs -> CREATE the job (+ the Picking lock), RETURN the job
// this key already made, NOT_ELIGIBLE (the form runs the old save instead) or REJECT (a message, nothing written).
// Stage switches: a case whose stage is off goes back to the old save. 1c (LOADING_BAY, BIN_MOVES): sql_node_PSmove's rows.
const ASYNC_PICKING_ENABLED = true;
const STAGE = { FULL_PICKING: true, LOADING_BAY: true, BIN_MOVES: true, AUTO_COMPLETE_GD: false, PICKING_PLAN: false, FORCE_COMPLETE: true };
const LOCK_STALE_SEC = 900;
const MAX_MOVED_GDS = 25;
const MAX_MOVED_LINES = 500;
const MAX_FC_GDS = 25;
const MAX_FC_LINES = 2000;
// the classic force complete re-saves every delivery line by line: refused above this (it took dev down at 500, 10-20)
const CLASSIC_FC_LINES = 500;
// classic_ok of a FORCE_COMPLETE: "1" when today's classic force complete takes the Picking's size (every NOT_ELIGIBLE carries it)
const fcClassicOk = function fcClassicOk(fcRows) {
  const gds = (Array.isArray(fcRows) ? fcRows : fcRows ? [fcRows] : []).filter((r) => r && String(r.kind) === "G");
  const lines = gds.reduce((k, g) => k + (Number(g.line_count) || 0), 0);
  return lines <= CLASSIC_FC_LINES && gds.length <= MAX_FC_GDS ? "1" : "0";
};
// Picking 1d - FORCE_COMPLETE: refused / NOT_ELIGIBLE (today's classic force complete; classic_ok 0 when that would exceed
// its safe size) / null = create the job. fcRows: sql_node_PSfc (a G row per delivery on the Picking, one P row: its records)
const decideFc = function decideFc(guard, f, fcRows, base) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
  const n = (v) => Number(v) || 0;
  const rows = (Array.isArray(fcRows) ? fcRows : fcRows ? [fcRows] : []).filter((r) => r);
  const GDS = rows.filter((r) => s(r.kind) === "G");
  const P = rows.filter((r) => s(r.kind) === "P")[0] || {};
  const lines = GDS.reduce((k, g) => k + n(g.line_count), 0);
  const classicOk = fcClassicOk(rows);
  const reject = (code, why) => Object.assign({}, base, { result_code: code, result_message: why, classic_ok: classicOk });
  const old = (why) => Object.assign({}, base, { route: "NOT_ELIGIBLE", result_code: "NOT_ELIGIBLE", result_message: why, classic_ok: classicOk });
  const status = s(f.to_status);
  if (status !== "In Progress") return reject("PK_FC_NOT_IN_PROGRESS", "Only an In Progress Picking can be force completed (this one is " + (status || "without a status") + ").");
  const openJob = s(f.open_job).split("|");
  if (openJob[0]) {
    if (openJob[1] === "REQUIRES_REVIEW") return reject("400", "A previous confirmation of this Picking stopped half-way and is under review (job " + openJob[0] + "). Please contact support before force completing it.");
    return reject("409", "This Picking is still being confirmed in the background (job " + openJob[0] + "). Wait a moment, then try again.");
  }
  if (n(f.is_processing) === 1 && n(f.lock_age_sec) <= LOCK_STALE_SEC) return reject("400", "Picking is under processing. Please try again later.");
  if (!STAGE.FORCE_COMPLETE) return old("the background force complete is switched off");
  if (s(f.picking_after) === "Sales Order") return old("Picking Plan pickings use the classic force complete");
  if (n(f.allow_full_picking) === 1) return old("Full Picking uses the classic force complete");
  if (n(f.auto_completed_gd) === 1) return old("Auto Complete GD uses the classic force complete");
  if (n(f.setup_loading_bay) === 1 || n(f.is_loading_bay) === 1) return old("Loading Bay uses the classic force complete");
  for (const g of GDS) {
    if (n(g.serial_items) > 0) return old("Goods Delivery " + s(g.delivery_no) + " has serial-numbered items: the classic force complete");
    if (n(g.select_picking) === 1) return old("Goods Delivery " + s(g.delivery_no) + " uses select picking: the classic force complete");
    if (n(g.linked) > 0) return old("Goods Delivery " + s(g.delivery_no) + " is linked to internal trading: the classic force complete");
  }
  if (GDS.length > MAX_FC_GDS || lines > MAX_FC_LINES) return reject("PK_FC_TOO_BIG", "This Picking has " + GDS.length + " deliveries and " + lines + " delivery lines; a force complete takes at most " + MAX_FC_GDS + " deliveries and " + MAX_FC_LINES + " lines. Nothing was saved.");
  if (n(P.rec_count) <= 0) return reject("PK_FC_NO_RECORDS", "Nothing has been picked on this Picking: cancel it instead.");
  const busy = GDS.find((g) => n(g.other_job) > 0);
  if (busy) return reject("409", "Goods Delivery " + s(busy.delivery_no) + " is being confirmed on another Picking in the background. Wait a moment, then try again.");
  return null;
};
const submitDecide = function submitDecide(guard, rows, moveRows, fcRows) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
  const n = (v) => Number(v) || 0;
  const f = (Array.isArray(rows) ? rows : rows ? [rows] : []).filter((r) => r)[0] || {};
  const base = { route: "REJECT", jobRows: [], needJob: "NO", lockRows: [], needLock: "NO", result_code: "400", result_message: "", job_id: "", job_status: "", classic_ok: "" };
  const reject = (why) => Object.assign({}, base, { result_message: why });
  const old = (why) => Object.assign({}, base, { route: "NOT_ELIGIBLE", result_code: "NOT_ELIGIBLE", result_message: why });
  const keyJob = s(f.key_job).split("|");
  if (keyJob[0]) return Object.assign({}, base, { route: "RETURN", result_code: "200", result_message: "already submitted", job_id: keyJob[0], job_status: keyJob[1] || "" });
  if (!ASYNC_PICKING_ENABLED) return Object.assign(old("the background save is switched off"), guard.operation === "FORCE_COMPLETE" ? { classic_ok: fcClassicOk(fcRows) } : {});
  if (!s(f.id) || String(f.is_deleted) === "1") return reject("Picking not found");
  if (s(f.organization_id) !== guard.organizationId) return reject("the Picking belongs to another organization");
  const status = s(f.to_status);
  if (status === "Completed") return reject("Picking is already completed");
  if (status === "Cancelled") return reject("Picking is cancelled. Unable to process picking.");
  // a Goods Delivery this Picking names is being saved in the background (GD Edit V2 / GD Completed V2)
  if (s(f.gd_busy)) return reject("Goods Delivery " + s(f.gd_busy) + " is being saved in the background. Wait a moment, then try again.");
  const fcGo = guard.operation === "FORCE_COMPLETE";
  if (fcGo) { const stop = decideFc(guard, f, fcRows, base); if (stop) return stop; }
  let moves = 0;
  if (!fcGo) {
  if (status === "Draft") return old("a Draft Picking is completed by the classic save");
  const openJob = s(f.open_job).split("|");
  if (openJob[0]) {
    if (openJob[1] === "REQUIRES_REVIEW") return reject("A previous confirmation of this Picking stopped half-way and is under review (job " + openJob[0] + "). Please contact support before picking again.");
    return reject("This Picking is still being confirmed in the background (job " + openJob[0] + "). Wait a moment, then reopen it.");
  }
  if (n(f.is_processing) === 1 && n(f.lock_age_sec) <= LOCK_STALE_SEC) return reject("Picking is under processing. Please try again later.");
  if (s(f.picking_after) === "Sales Order" && !STAGE.PICKING_PLAN) return old("Picking Plan pickings use the classic save");
  if (n(f.allow_full_picking) === 1 && !STAGE.FULL_PICKING) return old("Full Picking uses the classic save");
  // Loading Bay is the setup's flag, as classic PICKING passes it (the Picking's own copy counts only while the stage is off)
  const bay = n(f.setup_loading_bay) === 1;
  if (!STAGE.LOADING_BAY && (bay || n(f.is_loading_bay) === 1)) return old("Loading Bay uses the classic save");
  if (bay && n(f.auto_completed_gd) === 1) return reject("Picking Setup has both Loading Bay and Auto Complete GD enabled. Auto Complete GD skips the Created state that the loading bay move depends on, which would strand the reserved stock at the source bin. Please turn off Auto Complete GD.");
  if (n(f.auto_completed_gd) === 1 && !STAGE.AUTO_COMPLETE_GD) return old("Auto Complete GD uses the classic save");
  const mv = (Array.isArray(moveRows) ? moveRows : moveRows ? [moveRows] : []).filter((r) => r);
  const R = mv.filter((r) => s(r.kind) === "R");
  const GDS = mv.filter((r) => s(r.kind) === "G");
  if (bay) {
    const missing = R.filter((r) => n(r.bay_bad) === 1).map((r) => s(r.label)).filter((x, i, a) => x && a.indexOf(x) === i);
    if (missing.length) return reject("Loading Bay is enabled but Target Location is missing (or the same as the source bin) on these picked items: " + missing.join(", ") + ". Set a loading bay bin on every picked line before completing.");
  }
  const moved = R.filter((r) => n(r.moved) === 1);
  if (moved.length) {
    if (!bay && !STAGE.BIN_MOVES) return old(moved.length + " line(s) move stock to another bin or batch: the classic save");
    if (n(f.allow_full_picking) === 1) return old("Full Picking with a bin / batch move uses the classic save");
    if (moved.some((r) => s(r.hu))) return old("a moved line is in a handling unit: the classic save");
    for (const g of GDS) {
      if (n(g.serial_items) > 0) return old("Goods Delivery " + s(g.delivery_no) + " has serial-numbered items: the classic save");
      if (n(g.select_picking) === 1) return old("Goods Delivery " + s(g.delivery_no) + " uses select picking: the classic save");
      if (n(g.linked) > 0) return old("Goods Delivery " + s(g.delivery_no) + " is linked to internal trading: the classic save");
    }
    if (GDS.length > MAX_MOVED_GDS) return reject("This confirmation moves stock on " + GDS.length + " deliveries; at most " + MAX_MOVED_GDS + " can be saved together. Confirm it in smaller Pickings.");
    const lines = GDS.reduce((k, g) => k + n(g.line_count), 0);
    if (lines > MAX_MOVED_LINES) return reject("Moving picked stock to another bin or batch is not available yet above " + MAX_MOVED_LINES + " delivery lines in one confirmation (these deliveries have " + lines + "). Nothing was saved.");
    const busy = GDS.find((g) => n(g.other_job) > 0);
    if (busy) return reject("Goods Delivery " + s(busy.delivery_no) + " is being confirmed on another Picking in the background. Wait a moment, then try again.");
  }
  moves = (bay ? STAGE.LOADING_BAY : STAGE.BIN_MOVES) ? 1 : 0;
  }
  const dbNow = s(f.db_now);
  // PREPARE moves stock only on a job these switches cleared (a stored target can appear after SUBMIT)
  let request = guard.request;
  try { request = JSON.stringify(Object.assign(JSON.parse(guard.request), { moves: moves })); } catch (e) { request = guard.request; }
  return Object.assign({}, base, {
    route: "CREATE",
    jobRows: [{ organization_id: guard.organizationId, plant_id: s(f.plant_id), command: "CONFIRM_PICKING", idempotency_key: guard.idempotencyKey, job_status: "QUEUED", progress_percent: 0, progress_message: "Queued for processing", attempt_count: 0, row_version: 0, cancel_requested: 0, request_payload: request, picking_id: guard.pickingId, picking_no: s(f.to_id), line_count: guard.lineCount, queued_at: dbNow }],
    needJob: "YES", lockRows: [{ id: guard.pickingId, is_processing: 1 }], needLock: "YES", result_code: "200", result_message: "queued", job_status: "QUEUED",
  });
};
const guard = [{{node:code_node_PSguard.data}}][0];
const res = submitDecide(guard, [{{node:sql_node_PSfacts.data}}][0], [{{node:sql_node_PSmove.data}}][0], [{{node:sql_node_PSfc.data}}][0]);
console.log("submit decide", JSON.stringify({ route: res.route, code: res.result_code, message: res.result_message, job: res.job_id }));
return res;

// PICKING_ASYNC_SUBMIT - Result: the job read back by its key is the answer (QUEUED / an earlier job of the same click)
const submitResult = function submitResult(guard, decide, rows) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
  const job = (Array.isArray(rows) ? rows : rows ? [rows] : []).filter((r) => r && s(r.id))[0] || null;
  if (!job) return { route: "REJECT", result_code: "400", result_message: "the request could not be queued; press the button again", job_id: "", job_status: "", picking_id: guard.pickingId };
  const failed = s(job.job_status) === "FAILED" || s(job.job_status) === "REQUIRES_REVIEW";
  return { route: decide.route === "CREATE" ? "QUEUED" : "EXISTING", result_code: failed ? "400" : "200", result_message: failed ? s(job.error_message) || s(job.progress_message) : s(job.progress_message) || "queued", job_id: s(job.id), job_status: s(job.job_status), picking_id: guard.pickingId };
};
const guard = [{{node:code_node_PSguard.data}}][0];
const decide = [{{node:code_node_PSdecide.data}}][0];
const res = submitResult(guard, decide, [{{node:sql_node_PSback.data}}][0]);
console.log("submit result", JSON.stringify(res));
return res;
